-- Per-store invoice template: logo, seller details and footer used by the PDF export.
-- logo is a data: URL (PNG, JPEG, WebP or SVG) so no file uploads are needed on shared hosting.
CREATE TABLE IF NOT EXISTS store_invoice_settings (
  store_id INT UNSIGNED NOT NULL,
  logo MEDIUMTEXT NULL,
  legal_name VARCHAR(160) NULL,
  tax_number VARCHAR(40) NULL,
  cr_number VARCHAR(40) NULL,
  address VARCHAR(255) NULL,
  phone VARCHAR(40) NULL,
  email VARCHAR(160) NULL,
  accent_color VARCHAR(16) NULL,
  vat_rate DECIMAL(5,2) NOT NULL DEFAULT 0,
  footer_note VARCHAR(500) NULL,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (store_id),
  CONSTRAINT fk_invset_store FOREIGN KEY (store_id) REFERENCES stores (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- DEXEL: wordmark and contact details from dexelsa.com
INSERT IGNORE INTO store_invoice_settings (store_id, logo, legal_name, address, phone, email, accent_color, footer_note)
SELECT id, 'data:image/svg+xml;base64,', 'ديكسل — DEXEL', 'الرياض، المملكة العربية السعودية', '+966 53 516 6113', 'dexelagency@gmail.com', '#B96F47', 'شكراً لثقتكم بديكسل · dexelsa.com'
